#!/usr/bin/env bash
# Builds Glint.app from the Xcode project generated by project.yml (XcodeGen): MLX's Metal
# kernels, the asset-catalog icon, the String Catalog, Sparkle and glint-mcp all come from the
# Xcode build. Signs ad hoc unless SIGN_IDENTITY is set.
#
#   scripts/build_app.sh [debug|release]
#   SIGN_IDENTITY="Developer ID Application: …" scripts/build_app.sh release
#
# One-time setup: brew install xcodegen; xcodebuild -downloadComponent MetalToolchain
set -euo pipefail

case "${1:-release}" in
  debug) CONFIG=Debug ;;
  *) CONFIG=Release ;;
esac
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
BUILD="$ROOT/build"
APP="$BUILD/Glint.app"
DERIVED="$BUILD/DerivedData"
PRODUCTS="$DERIVED/Build/Products/$CONFIG"

cd "$ROOT"
echo "▸ Generating Glint.xcodeproj"
xcodegen generate --quiet

echo "▸ Building ($CONFIG, Apple silicon)"
# ARCHS on the command line also reaches the Swift package targets (Float16 and MLX: arm64 only).
xcodebuild build -project Glint.xcodeproj -scheme Glint -configuration "$CONFIG" \
  -destination 'platform=macOS,arch=arm64' -derivedDataPath "$DERIVED" \
  ARCHS=arm64 ONLY_ACTIVE_ARCH=YES CODE_SIGN_IDENTITY=- -quiet 2>&1 \
  | grep -vE "iOSSimulator|DVTErrorPresenter|CoreSimulator|^(Domain|Code|Failure Reason|Recovery Suggestion):|^--$|^$" || true
test -x "$PRODUCTS/Glint.app/Contents/MacOS/Glint" || { echo "✗ build failed"; exit 1; }
test -f "$PRODUCTS/Glint.app/Contents/Resources/mlx-swift_Cmlx.bundle/Contents/Resources/default.metallib" \
  || { echo "✗ MLX metallib missing — run: xcodebuild -downloadComponent MetalToolchain"; exit 1; }

rm -rf "$APP"
ditto "$PRODUCTS/Glint.app" "$APP"

echo "▸ String Catalog"
STRINGS=$(find "$DERIVED/Build/Intermediates.noindex" -name "*.stringsdata" -path "*$CONFIG*" \
  \( -path "*/Glint.build/*" -o -path "*/GlintUI.build/*" \) | sort -u)
if [[ -n "$STRINGS" ]]; then
  # shellcheck disable=SC2086
  xcrun xcstringstool sync App/Localizable.xcstrings --stringsdata $STRINGS
fi

# The hardened runtime's library validation refuses to load an ad hoc framework (Sparkle)
# into an ad hoc process, so local builds sign without it. Developer ID builds, and the
# release scripts, always use it (notarization requires it).
IDENTITY="${SIGN_IDENTITY:--}"
RUNTIME=()
[[ "$IDENTITY" != "-" ]] && RUNTIME=(--options runtime --timestamp)
SIGN=(codesign --force ${RUNTIME[@]+"${RUNTIME[@]}"} --sign "$IDENTITY")

echo "▸ Signing ($IDENTITY)"
"${SIGN[@]}" "$APP/Contents/Frameworks/Sparkle.framework"
for dylib in "$APP"/Contents/Frameworks/*.dylib; do
  [[ -e "$dylib" ]] && "${SIGN[@]}" "$dylib"
done
"${SIGN[@]}" "$APP/Contents/MacOS/glint-mcp"
"${SIGN[@]}" --entitlements App/Glint.entitlements "$APP"
codesign --verify --strict "$APP"

echo "✓ $APP"
